import "./globals.css";
import Sidebar from "../components/sidebar";

export const metadata = {
  title: "Ember & Oak – Order Desk",
  description: "Manage subscription orders and customers for Ember & Oak coffee roastery",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body className="app-container">
        <Sidebar />
        <main className="content">{children}</main>
      </body>
    </html>
  );
}

import OrdersTable from "../components/ordersTable";
import { Order } from "../lib/store";

export const revalidate = 0;

async function getThisWeeksOrders(): Promise<Order[]> {
  const res = await fetch("/api/orders?range=this_week", {
    cache: "no-store",
  });
  if (!res.ok) {
    throw new Error("Failed to fetch orders");
  }
  return res.json();
}

export default async function Page() {
  const orders = await getThisWeeksOrders();

  const revenue = orders.reduce((sum, o) => sum + o.quantity * o.unitPrice, 0);
  const statusCounts = orders.reduce((acc, o) => {
    acc[o.status] = (acc[o.status] ?? 0) + 1;
    return acc;
  }, {} as Record<string, number>);

  return (
    <div className="page">
      <h1 className="page-title">This Week’s Subscription Orders</h1>
      <div className="summary">
        <div className="summary-card">
          <span className="summary-label">Revenue</span>
          <span className="summary-value">${revenue.toFixed(2)}</span>
        </div>
        <div className="summary-card">
          <span className="summary-label">Pending Roast</span>
          <span className="summary-value">{statusCounts["pending"] ?? 0}</span>
        </div>
        <div className="summary-card">
          <span className="summary-label">Roasted</span>
          <span className="summary-value">{statusCounts["roasted"] ?? 0}</span>
        </div>
      </div>
      <OrdersTable initialData={orders} />
    </div>
  );
}

