import { NextResponse } from 'next/server';
import { readData, writeData } from '@/lib/store';
import { randomUUID } from 'crypto';

interface Order {
  id: string;
  customerId: string;
  roastBatch: string;
  quantity: number;
  price: number;
  status: 'pending' | 'roasted' | 'shipped' | 'canceled';
  orderDate: string;
}

function isValidOrder(o: any): o is Order {
  return (
    typeof o.customerId === 'string' &&
    typeof o.roastBatch === 'string' &&
    typeof o.quantity === 'number' &&
    typeof o.price === 'number' &&
    ['pending', 'roasted', 'shipped', 'canceled'].includes(o.status) &&
    typeof o.orderDate === 'string'
  );
}

export async function GET() {
  const orders = await readData<Order>('orders');
  return NextResponse.json(orders);
}

export async function POST(request: Request) {
  const body = await request.json();
  if (!isValidOrder(body)) {
    return NextResponse.json({ error: 'Invalid order data' }, { status: 400 });
  }
  const orders = await readData<Order>('orders');
  const newOrder: Order = { ...body, id: randomUUID() };
  orders.push(newOrder);
  await writeData('orders', orders);
  return NextResponse.json(newOrder, { status: 201 });
}

export async function PUT(request: Request) {
  const body = await request.json();
  const { id, updates } = body;
  if (typeof id !== 'string' || typeof updates !== 'object') {
    return NextResponse.json({ error: 'Invalid payload' }, { status: 400 });
  }
  const orders = await readData<Order>('orders');
  const idx = orders.findIndex(o => o.id === id);
  if (idx === -1) {
    return NextResponse.json({ error: 'Order not found' }, { status: 404 });
  }
  const updated = { ...orders[idx], ...updates };
  if (!isValidOrder(updated)) {
    return NextResponse.json({ error: 'Invalid order updates' }, { status: 400 });
  }
  orders[idx] = updated;
  await writeData('orders', orders);
  return NextResponse.json(updated);
}

export async function DELETE(request: Request) {
  const body = await request.json();
  const { id } = body;
  if (typeof id !== 'string') {
    return NextResponse.json({ error: 'Invalid id' }, { status: 400 });
  }
  const orders = await readData<Order>('orders');
  const filtered = orders.filter(o => o.id !== id);
  if (filtered.length === orders.length) {
    return NextResponse.json({ error: 'Order not found' }, { status: 404 });
  }
  await writeData('orders', filtered);
  return NextResponse.json({ success: true });
}

