'use client';
import { useEffect, useState } from 'react';
import ExportButton from './exportButton';
import styles from './ordersTable.module.css';

type Order = {
  id: string;
  customerName: string;
  roastBatch: string;
  quantityG: number;
  priceCents: number;
  status: 'Pending' | 'Roasted' | 'Shipped';
  orderDate: string; // ISO
};

type SortConfig = {
  key: keyof Order;
  direction: 'asc' | 'desc';
};

export default function OrdersTable() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [filtered, setFiltered] = useState<Order[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string[]>([]);
  const [sortConfig, setSortConfig] = useState<SortConfig | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchOrders = async () => {
    try {
      const res = await fetch('/api/orders');
      if (!res.ok) throw new Error('Failed to load orders');
      const data: Order[] = await res.json();
      setOrders(data);
      setFiltered(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  useEffect(() => {
    let data = [...orders];
    if (search) {
      const lower = search.toLowerCase();
      data = data.filter(
        (o) =>
          o.customerName.toLowerCase().includes(lower) ||
          o.roastBatch.toLowerCase().includes(lower)
      );
    }
    if (statusFilter.length) {
      data = data.filter((o) => statusFilter.includes(o.status));
    }
    if (sortConfig) {
      data.sort((a, b) => {
        const aVal = a[sortConfig.key];
        const bVal = b[sortConfig.key];
        if (aVal < bVal) return sortConfig.direction === 'asc' ? -1 : 1;
        if (aVal > bVal) return sortConfig.direction === 'asc' ? 1 : -1;
        return 0;
      });
    }
    setFiltered(data);
  }, [orders, search, statusFilter, sortConfig]);

  const toggleStatusFilter = (status: string) => {
    setStatusFilter((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
  };

  const requestSort = (key: keyof Order) => {
    setSortConfig((prev) => {
      if (prev?.key === key) {
        return { key, direction: prev.direction === 'asc' ? 'desc' : 'asc' };
      }
      return { key, direction: 'asc' };
    });
  };

  const updateStatus = async (id: string, status: Order['status']) => {
    try {
      const res = await fetch('/api/orders', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, status }),
      });
      if (!res.ok) throw new Error('Update failed');
      setOrders((prev) =>
        prev.map((o) => (o.id === id ? { ...o, status } : o))
      );
    } catch (e) {
      console.error(e);
    }
  };

  if (loading) return <p className={styles.message}>Loading orders…</p>;
  if (error) return <p className={styles.error}>Error: {error}</p>;

  return (
    <section className={styles.container}>
      <h2 className={styles.title}>This Week’s Subscription Orders</h2>
      <div className={styles.controls}>
        <input
          type="search"
          placeholder="Search customers or batch"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className={styles.searchInput}
        />
        <div className={styles.filterChips}>
          {['Pending', 'Roasted', 'Shipped'].map((s) => (
            <button
              key={s}
              onClick={() => toggleStatusFilter(s)}
              className={`${styles.filterChip} ${
                statusFilter.includes(s) ? styles.active : ''
              }`}
            >
              {s}
            </button>
          ))}
        </div>
        <ExportButton data={filtered} filename="orders.csv" />
      </div>
      {filtered.length === 0 ? (
        <p className={styles.message}>No orders match your criteria.</p>
      ) : (
        <table className={styles.table}>
          <thead>
            <tr>
              <th onClick={() => requestSort('orderDate')} className={styles.sortable}>
                Date
              </th>
              <th onClick={() => requestSort('customerName')} className={styles.sortable}>
                Customer
              </th>
              <th onClick={() => requestSort('roastBatch')} className={styles.sortable}>
                Roast Batch
              </th>
              <th onClick={() => requestSort('quantityG')} className={styles.sortable}>
                Qty (g)
              </th>
              <th onClick={() => requestSort('priceCents')} className={styles.sortable}>
                Revenue
              </th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((o) => (
              <tr key={o.id}>
                <td>{new Date(o.orderDate).toLocaleDateString()}</td>
                <td>{o.customerName}</td>
                <td>{o.roastBatch}</td>
                <td>{o.quantityG}</td>
                <td>{`$${(o.priceCents / 100).toFixed(2)}`}</td>
                <td>
                  <select
                    value={o.status}
                    onChange={(e) => updateStatus(o.id, e.target.value as Order['status'])}
                    className={styles.statusSelect}
                  >
                    <option value="Pending">Pending</option>
                    <option value="Roasted">Roasted</option>
                    <option value="Shipped">Shipped</option>
                  </select>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

'use client';
import { useEffect, useState } from 'react';
import ExportButton from './exportButton';
import styles from './customersTable.module.css';

type Customer = {
  id: string;
  name: string;
  email: string;
  city: string;
  subscriptionActive: boolean;
  createdAt: string; // ISO
};

export default function CustomersTable() {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [filtered, setFiltered] = useState<Customer[]>([]);
  const [search, setSearch] = useState('');
  const [activeFilter, setActiveFilter] = useState<'all' | 'active' | 'inactive'>('all');
  const [sortKey, setSortKey] = useState<keyof Customer>('name');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchCustomers = async () => {
    try {
      const res = await fetch('/api/customers');
      if (!res.ok) throw new Error('Failed to load customers');
      const data: Customer[] = await res.json();
      setCustomers(data);
      setFiltered(data);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCustomers();
  }, []);

  useEffect(() => {
    let data = [...customers];
    if (search) {
      const lower = search.toLowerCase();
      data = data.filter(
        (c) =>
          c.name.toLowerCase().includes(lower) ||
          c.email.toLowerCase().includes(lower) ||
          c.city.toLowerCase().includes(lower)
      );
    }
    if (activeFilter !== 'all') {
      data = data.filter(
        (c) => c.subscriptionActive === (activeFilter === 'active')
      );
    }
    data.sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];
      if (aVal < bVal) return sortDir === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });
    setFiltered(data);
  }, [customers, search, activeFilter, sortKey, sortDir]);

  const requestSort = (key: keyof Customer) => {
    if (sortKey === key) {
      setSortDir((prev) => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  if (loading) return <p className={styles.message}>Loading customers…</p>;
  if (error) return <p className={styles.error}>Error: {error}</p>;

  return (
    <section className={styles.container}>
      <h2 className={styles.title}>Customer List</h2>
      <div className={styles.controls}>
        <input
          type="search"
          placeholder="Search name, email, city"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          className={styles.searchInput}
        />
        <div className={styles.filterGroup}>
          <button
            onClick={() => setActiveFilter('all')}
            className={`${styles.filterBtn} ${activeFilter === 'all' ? styles.active : ''}`}
          >
            All
          </button>
          <button
            onClick={() => setActiveFilter('active')}
            className={`${styles.filterBtn} ${activeFilter === 'active' ? styles.active : ''}`}
          >
            Active
          </button>
          <button
            onClick={() => setActiveFilter('inactive')}
            className={`${styles.filterBtn} ${activeFilter === 'inactive' ? styles.active : ''}`}
          >
            Inactive
          </button>
        </div>
        <ExportButton data={filtered} filename="customers.csv" />
      </div>
      {filtered.length === 0 ? (
        <p className={styles.message}>No customers match your criteria.</p>
      ) : (
        <table className={styles.table}>
          <thead>
            <tr>
              <th onClick={() => requestSort('name')} className={styles.sortable}>Name</th>
              <th onClick={() => requestSort('email')} className={styles.sortable}>Email</th>
              <th onClick={() => requestSort('city')} className={styles.sortable}>City</th>
              <th onClick={() => requestSort('createdAt')} className={styles.sortable}>Joined</th>
              <th>Status</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((c) => (
              <tr key={c.id}>
                <td>{c.name}</td>
                <td>{c.email}</td>
                <td>{c.city}</td>
                <td>{new Date(c.createdAt).toLocaleDateString()}</td>
                <td>{c.subscriptionActive ? 'Active' : 'Inactive'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </section>
  );
}

'use client';

import { useRef, useState } from 'react';

interface ExportButtonProps {
  filename: string;
  headers: string[];
  rows: (string | number)[][];
}

export default function ExportButton({ filename, headers, rows }: ExportButtonProps) {
  const [exported, setExported] = useState(false);
  const timeoutRef = useRef<number | null>(null);

  const handleExport = () => {
    const escapeCell = (cell: string | number) => {
      const str = String(cell);
      if (str.includes(',') || str.includes('"') || str.includes('\n')) {
        return `"${str.replace(/"/g, '""')}"`;
      }
      return str;
    };

    const csvContent = [
      headers.map(escapeCell).join(','),
      ...rows.map(row => row.map(escapeCell).join(','))
    ].join('\n');

    const blob = new Blob(['\uFEFF' + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${filename}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    if (timeoutRef.current !== null) {
      window.clearTimeout(timeoutRef.current);
    }
    setExported(true);
    timeoutRef.current = window.setTimeout(() => {
      setExported(false);
      timeoutRef.current = null;
    }, 1600);
  };

  return (
    <button
      className={`export-btn ${exported ? 'export-btn--exported' : ''}`}
      onClick={handleExport}
      type="button"
      aria-label="Export current view as CSV"
    >
      <span key={exported ? 'exported' : 'idle'} className="export-btn__label">
        {exported ? 'Exported' : 'Export CSV'}
      </span>
    </button>
  );
}

import { promises as fs } from "fs";
import path from "path";

type StoreName = "orders" | "customers";

async function ensureDir(dir: string) {
  try {
    await fs.mkdir(dir, { recursive: true });
  } catch {}
}

async function readStore<T>(name: StoreName, defaultValue: T): Promise<T> {
  if (typeof window !== "undefined") {
    const raw = localStorage.getItem(name);
    if (raw) {
      try {
        return JSON.parse(raw) as T;
      } catch {}
    }
    return defaultValue;
  }
  const filePath = path.join(process.cwd(), "data", `${name}.json`);
  try {
    const data = await fs.readFile(filePath, "utf8");
    return JSON.parse(data) as T;
  } catch {
    return defaultValue;
  }
}

async function writeStore<T>(name: StoreName, data: T): Promise<void> {
  if (typeof window !== "undefined") {
    localStorage.setItem(name, JSON.stringify(data));
    return;
  }
  const dir = path.join(process.cwd(), "data");
  await ensureDir(dir);
  const filePath = path.join(dir, `${name}.json`);
  await fs.writeFile(filePath, JSON.stringify(data, null, 2), "utf8");
}

export { readStore, writeStore };
